280	    /// Each reference to an imported name in `prompt`, then in the system
281	    /// prompt, once, in the order they first appear.
282	    fn references<'a>(&'a self, prompt: &'a str) -> Vec<&'a str> {
283	        let mut references = Vec::new();
284	        for text in std::iter::once(prompt).chain(self.system_prompt.as_deref()) {
285	            for piece in pieces(text) {
286	                if let Piece::Reference(reference, name) = piece
287	                    && self.imports.has(name)
288	                    && !references.contains(&reference)
289	                {
290	                    references.push(reference);
291	                }
292	            }
293	        }
294	        references
295	    }
