297	    /// `text` with each reference to an imported name replaced by what it
298	    /// resolved to, and everything else as it is.
299	    fn resolve(&self, text: &str, resolved: &BTreeMap<String, String>) -> String {
300	        pieces(text)
301	            .into_iter()
302	            .map(|piece| match piece {
303	                Piece::Reference(reference, name) if self.imports.has(name) => {
304	                    resolved.get(reference).map_or(reference, String::as_str)
305	                }
306	                Piece::Reference(text, _) | Piece::Text(text) => text,
307	            })
308	            .collect()
309	    }
