311	    /// Reads back an anchor saved with [`Self::source`], with the prompt it
312	    /// holds. Anchors saved by earlier versions, their text as quoted pieces
313	    /// or as prose, read back too.
314	    pub fn parse(source: &str) -> Option<(Self, String)> {
315	        let mut imports = Imports::default();
316	        let mut lines = source.lines();
317	        let name = loop {
318	            let line = lines.next()?;
319	            if let Some(name) = line
320	                .strip_prefix("export ")
321	                .unwrap_or(line)
322	                .strip_prefix("anchor ")
323	                .and_then(|rest| rest.strip_suffix(':'))
324	            {
325	                break name.to_string();
326	            }
327	            imports.add_from_source(line);
328	        };
329	        if lines.next()?.trim() != "userPrompt:" {
330	            return None;
331	        }
332	        let lines: Vec<&str> = lines.collect();
333	        let (prompt, mut rest) = match read_escaped(&lines, PROMPT_INDENT) {
334	            Some(read) => read,
335	            None => {
336	                // Prompt lines are indented deeper, so only the properties
337	                // themselves match these lines.
338	                let property = |line: &&str| {
339	                    *line == SYSTEM_PROMPT_LINE
340	                        || *line == ATTACHED_TEXT_LINE
341	                        || *line == SLICED_LINE
342	                        || line.starts_with(MODE_PREFIX)
343	                };
344	                let end = lines.iter().position(property).unwrap_or(lines.len());
345	                let prompt = &lines[..end];
346	                let prompt = prompt.strip_suffix(&[""]).unwrap_or(prompt);
347	                (read_block(prompt), &lines[end..])
348	            }
349	        };
350	        // A blank line separates each property from the next.
351	        rest = rest.strip_prefix(&[""]).unwrap_or(rest);
352	        let mut mode = None;
353	        if let Some(key) = rest.first().and_then(|line| line.strip_prefix(MODE_PREFIX)) {
354	            mode = SendMode::from_key(key.trim());
355	            rest = &rest[1..];
356	            rest = rest.strip_prefix(&[""]).unwrap_or(rest);
357	        }
358	        let sliced = rest.first() == Some(&SLICED_LINE);
359	        if sliced {
360	            rest = &rest[1..];
361	            rest = rest.strip_prefix(&[""]).unwrap_or(rest);
362	        }
363	        let mut attached_text = Vec::new();
364	        if rest.first() == Some(&ATTACHED_TEXT_LINE) {
365	            rest = &rest[1..];
366	            let mut quoted: Vec<Vec<String>> = Vec::new();
367	            while let Some(line) = rest.first() {
368	                if line
369	                    .strip_prefix(PROMPT_INDENT)
370	                    .and_then(|key| key.strip_prefix(ATTACHMENT_KEY))
371	                    .is_some_and(|key| key.ends_with(':'))
372	                {
373	                    let (text, after) = read_escaped(&rest[1..], ATTACHMENT_INDENT)?;
374	                    attached_text.push(text);
375	                    rest = after;
376	                    continue;
377	                } else if *line == OLD_ATTACHMENT_ITEM {
378	                    quoted.push(Vec::new());
379	                } else if let Some(line) = line.strip_prefix(OLD_ATTACHMENT_LINE_PREFIX) {
380	                    quoted.last_mut()?.push(unquote(line)?);
381	                } else {
382	                    break;
383	                }
384	                rest = &rest[1..];
