485	/// Adds `text` to `source` as a multi-line escape block at `indent`, which
486	/// Piton keeps exactly as it is. Its fence is three backslashes, or one more
487	/// than any line of the text made only of backslashes, so nothing in the text
488	/// closes it early.
489	fn push_block(source: &mut String, indent: &str, text: &str) {
490	    let fence = "\\".repeat(fence_length(text));
491	    writeln!(source, "{indent}{fence}").ok();
492	    for line in text.split('\n') {
493	        let line = line.trim_end_matches('\r');
494	        if line.is_empty() {
495	            source.push('\n');
496	        } else {
497	            writeln!(source, "{indent}{line}").ok();
498	        }
499	    }
500	    writeln!(source, "{indent}{fence}").ok();
501	}
