503	/// How many backslashes fence `text`'s escape block.
504	fn fence_length(text: &str) -> usize {
505	    text.split('\n')
506	        .map(str::trim)
507	        .filter(|line| !line.is_empty() && line.chars().all(|c| c == '\\'))
508	        .map(|line| line.len() + 1)
509	        .max()
510	        .unwrap_or(0)
511	        .max(3)
512	}
