514	/// The text of an escape block written by [`push_block`] at `indent` at the
515	/// start of `lines`, and the lines after it; `None` when `lines` don't start
516	/// with one.
517	fn read_escaped<'a, 'b>(lines: &'a [&'b str], indent: &str) -> Option<(String, &'a [&'b str])> {
518	    let fence = lines.first()?.strip_prefix(indent)?;
519	    if fence.len() < 3 || !fence.chars().all(|c| c == '\\') {
520	        return None;
521	    }
522	    let close = format!("{indent}{fence}");
523	    let end = 1 + lines[1..].iter().position(|line| *line == close)?;
524	    let text = lines[1..end]
525	        .iter()
526	        .map(|line| line.strip_prefix(indent).unwrap_or(line.trim_start()))
527	        .collect::<Vec<_>>()
528	        .join("\n");
529	    Some((text, &lines[end + 1..]))
530	}
