438	/// How many messages a fed run was sent, its prompt the first, how many the
439	/// harness took in, and how many results it reported, so the result that
440	/// answers the last of them is known. Claude Code takes a message in once it
441	/// finishes what it is doing, and says so by replaying it: one taken in while
442	/// it is still at work joins what it is doing, and is answered by the same
443	/// result.
444	#[derive(Clone, Copy, Debug, PartialEq)]
445	pub struct Messages {
446	    sent: usize,
447	    taken: usize,
448	    results: usize,
449	}
450	
451	impl Default for Messages {
452	    fn default() -> Self {
453	        Self {
454	            sent: 1,
455	            taken: 0,
456	            results: 0,
457	        }
458	    }
459	}
460	
461	impl Messages {
462	    /// Another message was sent.
463	    pub fn sent(&mut self) {
464	        self.sent += 1;
465	    }
466	
467	    /// Reads a line of Claude Code's output. For a result, returns whether it
468	    /// answers every message sent: every one was taken in before it, or
469	    /// there is a result for each (should a harness not replay what it takes).
470	    pub fn read(&mut self, line: &Value) -> Option<bool> {
471	        let top_level = line
472	            .get("parent_tool_use_id")
473	            .is_none_or(|parent| parent.is_null());
474	        match str_at(line, "/type").as_deref() {
475	            Some("user")
476	                if top_level && line.get("isReplay").and_then(Value::as_bool) == Some(true) =>
477	            {
478	                self.taken += 1;
479	                None
480	            }
481	            Some("result") => {
482	                self.results += 1;
483	                Some(self.taken >= self.sent || self.results >= self.sent)
484	            }
485	            _ => None,
486	        }
487	    }
488	
489	    /// `events`, parsed from `line`, as they are for a fed run: a result that
490	    /// leaves a message unanswered is an answer, and the run goes on.
491	    pub fn events(&mut self, line: &Value, events: Vec<HarnessEvent>) -> Vec<HarnessEvent> {
492	        Self::relabel(self.read(line), events)
493	    }
494	
495	    fn relabel(last: Option<bool>, events: Vec<HarnessEvent>) -> Vec<HarnessEvent> {
496	        if last != Some(false) {
497	            return events;
498	        }
499	        events
500	            .into_iter()
501	            .map(|event| match event {
502	                HarnessEvent::Finished { is_error, result } => {
503	                    HarnessEvent::Answered { is_error, result }
504	                }
505	                event => event,
506	            })
507	            .collect()
508	    }
509	}
