511	#[allow(clippy::too_many_arguments)]
512	fn run(
513	    agent: Agent,
514	    program: &Path,
515	    prompt: &str,
516	    system_prompt: Option<&str>,
517	    resume: Option<&Resume>,
518	    project_dir: &Path,
519	    tx: &mpsc::UnboundedSender<HarnessEvent>,
520	    feed: Option<&Feed>,
521	    stop: &Stop,
522	) -> Result<()> {
523	    // A conversation is only carried on by the agent it began with, and only
524	    // Claude Code can carry on a copy of one; otherwise a new one starts.
525	    let resume = resume.and_then(|resume| {
526	        let (began, id) = Agent::of_session(&resume.session);
527	        (began == agent && (!resume.fork || agent == Agent::Claude))
528	            .then(|| (id.to_string(), resume.fork))
529	    });
530	    let mut command = Command::new(program);
531	    let mut input = prompt_as_given(agent, prompt, system_prompt);
532	    match agent {
533	        Agent::Claude => {
534	            command.args([
535	                "-p",
536	                // The spec: the harness always runs in auto mode.
537	                "--permission-mode",
538	                "auto",
539	                "--output-format",
540	                "stream-json",
541	                "--verbose",
542	                "--include-partial-messages",
543	                // A resumed conversation otherwise keeps the system prompt of
544	                // its first run, and each prompt's own must apply, as its mode
545	                // may differ.
546	                "--system-prompt-snapshot",
547	                "off",
548	            ]);
549	            if let Some((session, fork)) = &resume {
550	                command.args(["--resume", session]);
551	                if *fork {
552	                    command.arg("--fork-session");
553	                }
554	            }
555	            if let Some(system_prompt) = system_prompt {
556	                command.args(["--append-system-prompt", system_prompt]);
557	            }
558	            // Fed, the prompt is the first of a stream of messages, each of
559	            // which the harness replays as it takes it in.
560	            if feed.is_some() {
561	                command.args(["--input-format", "stream-json", "--replay-user-messages"]);
562	                input = user_message(prompt);
563	            }
564	        }
565	        Agent::Codex => {
566	            command.args(["exec", "--json", "--full-auto", "--skip-git-repo-check"]);
567	            if let Some((session, _)) = &resume {
568	                command.args(["resume", session]);
569	            }
570	            // Read from standard input.
571	            command.arg("-");
572	        }
573	        Agent::OpenCode => {
574	            command.args(["run", "--format", "json"]);
575	            if let Some((session, _)) = &resume {
576	                command.args(["--session", session]);
577	            }
578	        }
579	    }
580	    let name = invocation(agent);
581	    if stop.is_stopped() {
582	        return Ok(());
583	    }
584	    command
585	        .current_dir(project_dir)
586	        .stdin(Stdio::piped())
587	        .stdout(Stdio::piped())
588	        .stderr(Stdio::piped());
589	    // Its own process group, so stopping it ends everything it started too.
590	    #[cfg(unix)]
591	    std::os::unix::process::CommandExt::process_group(&mut command, 0);
592	    let mut child = command
593	        .spawn()
594	        .with_context(|| format!("could not run `{name}`"))?;
595	    let stdin = child.stdin.take().context("the harness has no stdin");
596	    let stdout = child.stdout.take().context("the harness has no stdout");
597	    let stderr = child.stderr.take().context("the harness has no stderr");
598	    // Held from here on, so stopping the run ends it wherever it is.
599	    stop.hold(child);
600	    let (mut stdin, stdout, stderr) = (stdin?, stdout?, stderr?);
601	
602	    // The prompt goes over stdin so its length and leading characters never
603	    // collide with command-line parsing; dropping stdin ends it, unless the
604	    // run is fed, when it stays open for more.
605	    let written = stdin.write_all(input.as_bytes());
606	    if stop.is_stopped() {
607	        return Ok(());
608	    }
609	    written?;
610	    if let Some(feed) = feed {
611	        stdin.flush()?;
612	        feed.lock().stdin = Some(stdin);
613	        // Stopped meanwhile, its input stays closed.
614	        if stop.is_stopped() {
615	            feed.close();
616	        }
617	    } else {
618	        drop(stdin);
619	    }
620	    // Error output reaches the raw stream as it arrives, and is kept for the
621	    // error message should the run end without a result.
622	    let stderr = std::thread::spawn({
623	        let tx = tx.clone();
624	        move || {
625	            let mut text = String::new();
626	            for line in BufReader::new(stderr).lines() {
627	                let Ok(line) = line else { break };
628	                tx.unbounded_send(HarnessEvent::Output(line.clone())).ok();
629	                text.push_str(&line);
630	                text.push('\n');
631	            }
632	            text
633	        }
634	    });
635	
636	    let mut replying = Replying::default();
637	    for line in BufReader::new(stdout).lines() {
638	        // Stopped, nothing more it prints is taken.
639	        if stop.is_stopped() {
640	            break;
641	        }
642	        let line = line?;
643	        if line.trim().is_empty() {
644	            // Nothing to parse, but the raw stream shows lines as they arrived.
645	            // Once no one is listening, the run is stopped.
646	            if tx.unbounded_send(HarnessEvent::Output(line)).is_err() {
647	                stop.stop();
648	                return Ok(());
649	            }
650	            continue;
651	        }
652	        let events = match serde_json::from_str::<Value>(&line) {
653	            Ok(event) => {
654	                // The skills and agents this run has are offered as mentions.
655	                harness_mentions::remember(&event, project_dir);
656	                let events = parse(&event);
657	                match feed {
658	                    Some(feed) => feed.read(&event, events),
659	                    None => events,
660	                }
661	            }
662	            Err(_) => Vec::new(),
663	        };
664	        for event in std::iter::once(HarnessEvent::Output(line)).chain(events) {
665	            if tx.unbounded_send(replying.take(event)).is_err() {
666	                stop.stop();
667	                return Ok(());
668	            }
669	        }
670	    }
671	
672	    let status = stop.wait()?;
673	    // Stopped, it ended as it was asked to; what it left writing to its error
674	    // output is not waited on.
675	    if stop.is_stopped() {
676	        return Ok(());
677	    }
678	    let stderr = stderr.join().unwrap_or_default();
679	    if !replying.finished() {
680	        // A harness that ends without saying it finished, as OpenCode may,
681	        // finished with what it last wrote once it exits cleanly.
682	        if status.success() && agent != Agent::Claude {
683	            tx.unbounded_send(replying.finish()).ok();
684	            return Ok(());
685	        }
686	        let stderr = stderr.trim();
687	        if stderr.is_empty() {
688	            bail!("`{name}` exited with {status}");
689	        }
690	        bail!("{stderr}");
691	    }
692	    Ok(())
693	}
