331	/// `from` blended `t` of the way to `to`, at the tint's opacity.
332	fn blend(from: Hsla, to: Hsla, t: f32) -> Hsla {
333	    let t = t.clamp(0., 1.);
334	    // A grey has no hue of its own, so blending to or from one keeps the
335	    // other's hue, only fading its saturation, rather than passing through
336	    // whatever hue the grey happens to be given.
337	    const GREY: f32 = 0.05;
338	    let from_h = if from.s < GREY { to.h } else { from.h };
339	    let to_h = if to.s < GREY { from_h } else { to.h };
340	    let from = Hsla { h: from_h, ..from };
341	    let to = Hsla { h: to_h, ..to };
342	    // The shorter way round the hue circle, which from red to blue passes
343	    // through purple rather than green.
344	    let hue_step = (to.h - from.h + 0.5).rem_euclid(1.) - 0.5;
345	    Hsla {
346	        h: (from.h + hue_step * t).rem_euclid(1.),
347	        s: from.s + (to.s - from.s) * t,
348	        l: from.l + (to.l - from.l) * t,
349	        a: TINT_OPACITY,
350	    }
351	}
