353	/// How much of tab `ix`'s tint shows with the tint at `position`: all of it
354	/// while the tab is selected, alone or (for Code and Spec) with the other,
355	/// fading out over one tab either side.
356	fn tab_tint_shown(ix: usize, position: f32) -> f32 {
357	    let (first, last) = match TABS[ix] {
358	        SendMode::Code => (0., 1.),
359	        SendMode::Spec => (1., 2.),
360	        SendMode::Both | SendMode::Ask | SendMode::Freeform => (ix as f32, ix as f32),
361	    };
362	    // The tabs wrap around, so Code is as near Freeform as Chain is to Code.
363	    let count = TABS.len() as f32;
364	    let position = position.rem_euclid(count);
365	    let distance = [position - count, position, position + count]
366	        .into_iter()
367	        .map(|position| (first - position).max(position - last).max(0.))
368	        .fold(f32::MAX, f32::min);
369	    (1. - distance).clamp(0., 1.)
370	}
