542	/// A number of tokens, short: "850", "42.1k", "123k", "1.2M".
543	pub fn tokens_label(tokens: u64) -> String {
544	    let short = |value: f64, unit: &str| {
545	        if value < 100. {
546	            let text = format!("{value:.1}");
547	            format!("{}{unit}", text.trim_end_matches(".0"))
548	        } else {
549	            format!("{value:.0}{unit}")
550	        }
551	    };
552	    match tokens {
553	        0..1_000 => tokens.to_string(),
554	        1_000..1_000_000 => short(tokens as f64 / 1_000., "k"),
555	        _ => short(tokens as f64 / 1_000_000., "M"),
556	    }
557	}
