    /// Every event of a run, until it ends.
    fn all_events(events: futures::channel::mpsc::UnboundedReceiver<HarnessEvent>) -> Vec<HarnessEvent> {
        use futures::StreamExt as _;
        futures::executor::block_on(events.collect::<Vec<_>>())
